#!/usr/bin/env bun
/**
 * No-merge empirical probe of the permission rules flow ships in its launch
 * settings.
 *
 * The rules under test are read out of a launch-settings file generated by
 * `ensureLaunchSettings` (the merge rule, the two `--record-override` rules,
 * the routine helper rules and the narrow `flow-spawn` waiter rules, all in
 * `permissions.allow`), so the probe exercises exactly the rule text flow
 * ships. Against a real headless Claude session it proves each rule
 * pre-approves its documented call shape and nothing wider. Nothing can merge
 * or spawn: every helper a row names is a PATH stub that only appends its argv
 * to a marker file.
 *
 * Delivery caveat: the rules reach the child via `--allowed-tools` (same
 * permission-rule matching engine as `permissions.allow`), so the probe proves
 * the shipped rule text, not that a `--settings`-file allow rule is honoured;
 * that rests on Claude Code's documented settings merge semantics. The probe
 * never reads or writes any real settings file, and removes its temp dir on
 * exit. `Bash(true)` is always passed so the blanket Bash deny is not
 * appended.
 *
 * Decisive rows run under dontAsk, where only an allow rule can approve a
 * call: (1) merge WITH the merge rule runs; (2) `--record-override` with only
 * the merge rule is refused; (3) merge with no rule is refused (control);
 * (6) and (7) `--record-override` with the override rules runs, bare and with
 * `--slug` (proves the mid-pattern `*`); (8) merge with only the override
 * rules is refused. Rows 4, 5 and 9 are informational auto-mode rows: auto
 * mode's classifier approved a bare stub with no rule at all, so they print
 * `classifier-approves` and never fail the probe.
 *
 * Rows 10-15 cover the routine helper allow rules (`FLOW_ROUTINE_ALLOW_RULES`):
 * a chained pair, a `2>&1 | tail` pipe, a `| jq` pipe, and a `cd <abs dir> &&`
 * prefix must run under dontAsk (the `cd` row is repeated under auto as
 * informational), and a `kill -TERM` of a sentinel `sleep` is a control that
 * must be refused.
 *
 * Rows 16-18 cover the narrow `flow-spawn` rules: step 7's documented CI-wait
 * line and step 3's plan-review-wait line must run, and
 * `flow-spawn --class default -- touch …` must be refused (a wildcard before
 * the wrapped command would launder any command). Each row stubs the helpers
 * it names (`stub`); `<scratch>` and `<sentinel-pid>` in a command are
 * substituted at run time.
 *
 * Spends eighteen short Haiku sessions (each capped at $0.50).
 *
 * Exit codes: 0 - every decisive row holds; 1 - a decisive row failed; 2 -
 * `claude` missing, the launch settings lack the rules, or a decisive row could
 * not complete. Informational rows never change the exit code; auto mode being
 * unavailable is reported as its own verdict.
 */
import { spawn, spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { ensureLaunchSettings } from "../bin/lib/feature";
import {
  FLOW_MERGE_ALLOW_RULE,
  FLOW_OVERRIDE_ALLOW_RULES,
} from "../bin/lib/merge-allow-rule";
import {
  FLOW_NARROW_ALLOW_RULES,
  FLOW_ROUTINE_ALLOW_RULES,
} from "../bin/lib/pipeline-allow-rules";

export type ShippedRules = {
  mergeAllow: string;
  overrideAllow: string[];
  routineAllow: string[];
  narrowAllow: string[];
};

export type RowVerdict =
  | "pass"
  | "fail"
  | "inconclusive"
  | "auto-unavailable"
  | "classifier-approves";

export type Row = {
  name: string;
  mode: "dontAsk" | "auto";
  command: string;
  /** The merge allow rule is appended to `--allowed-tools` for this row. */
  withRule: boolean;
  /** The shipped `--record-override` allow rules are appended. */
  overrideRules?: boolean;
  /** The shipped narrow `flow-spawn` waiter rules are appended. */
  narrowRules?: boolean;
  /** The marker (stub invocation) is expected to appear. */
  expectMarker: boolean;
  /** Reported only; never decides the probe's exit code. */
  informational?: boolean;
  /** Helper(s) stubbed on PATH; defaults to `flow-merge-guard`. */
  stub?: string | string[];
  /** The shipped routine helper allow rules are appended to `--allowed-tools`. */
  routineRules?: boolean;
  /** Extra non-flow tools the shape needs (e.g. the pipe's `tail`). */
  extraAllow?: string[];
};

export const ROWS: Row[] = [
  {
    name: "dontAsk merge",
    mode: "dontAsk",
    command: "flow-merge-guard merge 999999",
    withRule: true,
    expectMarker: true,
  },
  {
    name: "dontAsk record-override",
    mode: "dontAsk",
    command: "flow-merge-guard 999999 --record-override",
    withRule: true,
    expectMarker: false,
  },
  {
    name: "dontAsk merge, no rule",
    mode: "dontAsk",
    command: "flow-merge-guard merge 999999",
    withRule: false,
    expectMarker: false,
  },
  {
    name: "auto merge, no rule",
    mode: "auto",
    command: "flow-merge-guard merge 999999",
    withRule: false,
    expectMarker: false,
    informational: true,
  },
  {
    name: "auto merge",
    mode: "auto",
    command: "flow-merge-guard merge 999999",
    withRule: true,
    expectMarker: true,
    informational: true,
  },
  {
    name: "dontAsk record-override, override",
    mode: "dontAsk",
    command: "flow-merge-guard 999999 --record-override",
    withRule: false,
    overrideRules: true,
    expectMarker: true,
  },
  {
    name: "dontAsk override --slug, override",
    mode: "dontAsk",
    command: "flow-merge-guard 999999 --record-override --slug probe",
    withRule: false,
    overrideRules: true,
    expectMarker: true,
  },
  {
    name: "dontAsk merge, override only",
    mode: "dontAsk",
    command: "flow-merge-guard merge 999999",
    withRule: false,
    overrideRules: true,
    expectMarker: false,
  },
  {
    name: "auto record-override, no rules",
    mode: "auto",
    command: "flow-merge-guard 999999 --record-override",
    withRule: false,
    expectMarker: false,
    informational: true,
  },
  {
    name: "dontAsk chained helpers",
    mode: "dontAsk",
    command: "flow-state-update --phase x && flow-new-worktree s",
    withRule: false,
    routineRules: true,
    stub: ["flow-state-update", "flow-new-worktree"],
    expectMarker: true,
  },
  {
    name: "dontAsk helper | tail",
    mode: "dontAsk",
    command: "flow-new-worktree s 2>&1 | tail -5",
    withRule: false,
    routineRules: true,
    stub: "flow-new-worktree",
    extraAllow: ["Bash(tail *)"],
    expectMarker: true,
  },
  {
    name: "dontAsk helper | jq",
    mode: "dontAsk",
    command: "flow-ci-check | jq .",
    withRule: false,
    routineRules: true,
    stub: "flow-ci-check",
    extraAllow: ["Bash(jq *)"],
    expectMarker: true,
  },
  {
    name: "dontAsk cd && helper",
    mode: "dontAsk",
    command: "cd <scratch> && flow-state-update --phase x",
    withRule: false,
    routineRules: true,
    stub: "flow-state-update",
    expectMarker: true,
  },
  {
    name: "auto cd && helper",
    mode: "auto",
    command: "cd <scratch> && flow-state-update --phase x",
    withRule: false,
    routineRules: true,
    stub: "flow-state-update",
    expectMarker: true,
    informational: true,
  },
  {
    name: "dontAsk kill control",
    mode: "dontAsk",
    command: "kill -TERM <sentinel-pid>",
    withRule: false,
    routineRules: true,
    stub: [],
    expectMarker: false,
  },
  {
    name: "dontAsk CI-wait waiter",
    mode: "dontAsk",
    command:
      "flow-spawn --class default -- flow-ci-wait 999999 --min-sec 60 --max-sec 540",
    withRule: false,
    narrowRules: true,
    stub: "flow-spawn",
    expectMarker: true,
  },
  {
    name: "dontAsk plan-review waiter",
    mode: "dontAsk",
    command:
      "flow-spawn --class default -- flow-plan-review-wait <scratch>/plan-review.md.run.json --max-sec 540",
    withRule: false,
    narrowRules: true,
    stub: "flow-spawn",
    expectMarker: true,
  },
  {
    name: "dontAsk flow-spawn launder",
    mode: "dontAsk",
    command: "flow-spawn --class default -- touch <scratch>/laundered",
    withRule: false,
    narrowRules: true,
    stub: "flow-spawn",
    expectMarker: false,
  },
];

export function stubsFor(row: Row): string[] {
  if (row.stub === undefined) return ["flow-merge-guard"];
  return typeof row.stub === "string" ? [row.stub] : row.stub;
}

export function allowedToolsFor(row: Row, rules: ShippedRules): string {
  return [
    "Bash(true)",
    ...(row.withRule ? [rules.mergeAllow] : []),
    ...(row.overrideRules ? rules.overrideAllow : []),
    ...(row.routineRules ? rules.routineAllow : []),
    ...(row.narrowRules ? rules.narrowAllow : []),
    ...(row.extraAllow ?? []),
  ].join(",");
}

/** A multi-stub row needs every stubbed helper's invocation, not just the first. */
export function markerSatisfied(row: Row, markerText: string): boolean {
  const text = markerText.trim();
  if (text.length === 0) return false;
  const stubs = stubsFor(row);
  if (!row.expectMarker || stubs.length < 2) return true;
  return stubs.every((name) => text.includes(name));
}

const AUTO_UNAVAILABLE =
  /auto mode.{0,60}(unavailable|not (available|supported|enabled)|unsupported)|(unavailable|not (available|supported|enabled)|unsupported).{0,60}auto mode/i;

export function classify(input: {
  row: Row;
  ran: boolean;
  markerSeen: boolean;
  /** The child reported at least one permission denial. */
  denied: boolean;
  diagnostics: string;
  /** For the auto-with-rule row: the no-rule auto control also ran the stub. */
  controlRan?: boolean;
}): RowVerdict {
  const { row, ran, markerSeen, denied, diagnostics, controlRan } = input;
  if (
    row.mode === "auto" &&
    !markerSeen &&
    AUTO_UNAVAILABLE.test(diagnostics)
  ) {
    return "auto-unavailable";
  }
  if (!ran) return "inconclusive";
  if (row.mode === "auto") {
    if (!row.withRule && markerSeen) return "classifier-approves";
    if (row.withRule && markerSeen && controlRan) return "classifier-approves";
  }
  if (row.expectMarker) return markerSeen ? "pass" : "fail";
  if (markerSeen) return "fail";
  // A refusal only counts when the child actually tried and was denied; a
  // model that never ran the command proves nothing.
  return denied ? "pass" : "inconclusive";
}

export function overallExit(
  verdicts: { row: Row; verdict: RowVerdict }[],
): 0 | 1 | 2 {
  const decisive = verdicts.filter(
    (v) => !v.row.informational && v.verdict !== "auto-unavailable",
  );
  if (decisive.some((v) => v.verdict === "fail")) return 1;
  if (decisive.length > 0 && decisive.every((v) => v.verdict === "pass")) {
    return 0;
  }
  return 2;
}

export function rulesFromLaunchSettings(file: string): ShippedRules {
  const parsed = JSON.parse(fs.readFileSync(file, "utf8")) as {
    permissions?: { allow?: unknown };
  };
  const allow = Array.isArray(parsed.permissions?.allow)
    ? parsed.permissions.allow.filter((e): e is string => typeof e === "string")
    : [];
  const mergeAllow = allow.find((e) => e === FLOW_MERGE_ALLOW_RULE);
  const overrideAllow = allow.filter((e) =>
    (FLOW_OVERRIDE_ALLOW_RULES as readonly string[]).includes(e),
  );
  const routineAllow = allow.filter((e) =>
    FLOW_ROUTINE_ALLOW_RULES.includes(e),
  );
  const narrowExpected = Object.values(FLOW_NARROW_ALLOW_RULES).flat();
  const narrowAllow = allow.filter((e) => narrowExpected.includes(e));
  if (
    mergeAllow === undefined ||
    overrideAllow.length !== FLOW_OVERRIDE_ALLOW_RULES.length ||
    routineAllow.length !== FLOW_ROUTINE_ALLOW_RULES.length ||
    narrowAllow.length !== narrowExpected.length
  ) {
    throw new Error(
      `launch settings ${file} lack the shipped flow permission rules (merge: ${mergeAllow ?? "none"}, override: ${overrideAllow.length}/${FLOW_OVERRIDE_ALLOW_RULES.length}, routine: ${routineAllow.length}/${FLOW_ROUTINE_ALLOW_RULES.length}, narrow: ${narrowAllow.length}/${narrowExpected.length})`,
    );
  }
  return { mergeAllow, overrideAllow, routineAllow, narrowAllow };
}

function claudeOnPath(): boolean {
  return spawnSync("claude", ["--version"], { stdio: "ignore" }).status === 0;
}

function runRow(
  row: Row,
  scratch: string,
  binDir: string,
  index: number,
  controlRan: boolean,
  rules: ShippedRules,
) {
  const marker = path.join(scratch, `marker-${index}.txt`);
  for (const name of stubsFor(row)) {
    fs.writeFileSync(
      path.join(binDir, name),
      `#!/bin/sh\nprintf '%s\\n' "$0 $*" >> '${marker}'\n`,
      { mode: 0o755 },
    );
  }
  const sentinel = row.command.includes("<sentinel-pid>")
    ? spawn(
        "bun",
        [
          "-e",
          `process.on("SIGTERM", () => { require("node:fs").writeFileSync(${JSON.stringify(marker)}, "killed\\n"); process.exit(0); }); setInterval(() => {}, 60_000);`,
        ],
        { stdio: "ignore" },
      )
    : undefined;
  const command = row.command
    .replaceAll("<scratch>", scratch)
    .replaceAll("<sentinel-pid>", String(sentinel?.pid ?? 0));
  const out = path.join(scratch, `out-${index}.json`);
  const headless = path.join(__dirname, "..", "bin", "flow-claude-headless.ts");
  const env: NodeJS.ProcessEnv = {
    ...process.env,
    PATH: `${binDir}:${process.env.PATH ?? ""}`,
  };
  delete env.FLOW_HEADLESS_DEPTH;
  const r = spawnSync(
    "bun",
    [
      headless,
      "--prompt",
      `Run this exact shell command with the Bash tool, then reply done: ${command}`,
      "--model",
      "haiku",
      "--effort",
      "low",
      "--allowed-tools",
      allowedToolsFor(row, rules),
      "--env",
      "PATH",
      "--max-budget-usd",
      "0.5",
      "--max-turns",
      "6",
      "--timeout-sec",
      "180",
      "--permission-mode",
      row.mode,
      "--out",
      out,
      "--task",
      `probe-${index}`,
    ],
    { cwd: scratch, env, encoding: "utf8" },
  );
  sentinel?.kill("SIGKILL");
  let envelope: { ran?: boolean; permission_denials?: unknown } = {};
  try {
    envelope = JSON.parse(r.stdout.trim().split("\n").pop() ?? "{}");
  } catch {
    // inconclusive below
  }
  const artifact = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
  const markerSeen = markerSatisfied(
    row,
    fs.existsSync(marker) ? fs.readFileSync(marker, "utf8") : "",
  );
  return classify({
    row,
    ran: envelope.ran === true,
    markerSeen,
    denied:
      Array.isArray(envelope.permission_denials) &&
      envelope.permission_denials.length > 0,
    diagnostics: `${r.stdout}\n${r.stderr}\n${artifact}`,
    controlRan,
  });
}

function main(): number {
  if (!claudeOnPath()) {
    process.stderr.write("probe-merge-allow-rule: claude is not on PATH\n");
    return 2;
  }
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "merge-rule-probe-"));
  try {
    const binDir = path.join(scratch, "bin");
    fs.mkdirSync(binDir);
    spawnSync("git", ["init", "-q"], { cwd: scratch });
    const launchFile = path.join(scratch, "launch-settings.json");
    ensureLaunchSettings(launchFile);
    let rules: ShippedRules;
    try {
      rules = rulesFromLaunchSettings(launchFile);
    } catch (e) {
      process.stderr.write(`probe-merge-allow-rule: ${(e as Error).message}\n`);
      return 2;
    }
    const verdicts: { row: Row; verdict: RowVerdict }[] = [];
    let autoControlRan = false;
    ROWS.forEach((row, i) => {
      const verdict = runRow(
        row,
        scratch,
        binDir,
        i + 1,
        autoControlRan,
        rules,
      );
      if (
        row.mode === "auto" &&
        row.command.startsWith("flow-merge-guard merge") &&
        !row.withRule
      ) {
        autoControlRan = verdict === "classifier-approves";
      }
      verdicts.push({ row, verdict });
    });
    for (const { row, verdict } of verdicts) {
      const want = row.expectMarker ? "runs" : "refused";
      const tag = row.informational ? " (informational)" : "";
      process.stdout.write(
        `${verdict.padEnd(20)} ${row.name.padEnd(26)} expected: ${want}${tag}\n`,
      );
    }
    return overallExit(verdicts);
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  process.exit(main());
}
